package com.system.recovery.controller; import com.system.recovery.service.RecoveryOrchestrator; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/approvals") public class ApprovalController { private final RecoveryOrchestrator o; public ApprovalController(RecoveryOrchestrator o){this.o=o;} @GetMapping public Object pending(){return o.pending();} @PostMapping("/{id}/approve") public Object approve(@PathVariable UUID id){return o.resolve(id,true);}@PostMapping("/{id}/reject") public Object reject(@PathVariable UUID id){return o.resolve(id,false);} }
